    "Un pago por Stripe te cuesta la comisión de procesamiento de Stripe, que Stripe cobra a la tarifa que fija para tu país. Una transferencia por Wise nunca pasa por Stripe, así que no te cuesta comisión de procesamiento y puedes pasarle ese ahorro a tu alumno. Para ir sobre seguro calculamos el descuento sugerido con nuestra propia estimación deliberadamente alta — {rate}% más una comisión fija pequeña, que corresponde a una tarjeta internacional con conversión de divisa — así la mayoría de los pagos te cuestan menos de lo que supusimos y el precio por Wise nunca te deja peor. Los dos precios se pueden editar.",
