  "web.features.item.getPaid.body":
    "Paquetes prepagados con tarjeta (Stripe) o Wise. El dinero llega antes de la clase — no después.",
  "web.features.item.globalPay.title": "Pagos flexibles en cualquier país",
  "web.features.item.globalPay.body":
    "Tarjeta con Stripe donde esté disponible, o transferencia directa con Wise en el resto del mundo. Tú eliges el riel; tus alumnos siempre pueden pagarte.",
  "web.features.item.reminders.title": "Recordatorios automáticos",
  "web.features.item.reminders.body":
    "Push y correo a 24 horas, 1 hora y 15 minutos antes. Menos faltas, sin trabajo extra para ti.",
  "web.features.item.chat.title": "Chat de clase integrado",
  "web.features.item.chat.body":
    "Mensajes y video directo dentro de la clase. Sin saltar a otras apps, todo en el mismo lugar.",
  "web.features.item.materials.title": "Materiales programados",
  "web.features.item.materials.body":
    "Sube archivos o pega enlaces. Elige cuándo enviárselos al alumno — al confirmar, 5 días antes o 1 hora antes.",
  "web.features.item.library.title": "Biblioteca de materiales por nivel",
  "web.features.item.library.body":
    "Organiza tus recursos por nivel y asígnalos a varios alumnos a la vez. Crea una vez, reutiliza siempre.",
  "web.features.item.notes.title": "Notas y progreso por alumno",
  "web.features.item.notes.body":
    "Ficha de cada alumno con notas, historial de clases y materiales asignados. Todo en un vistazo.",
  "web.features.item.pricing.title": "Paquetes y precios personalizados",
  "web.features.item.pricing.body":
    "Define paquetes de clases, precio por sesión, y ajusta el precio por alumno cuando lo necesites.",
  "web.features.item.homeScreen.title": "Agrégala a tu pantalla de inicio",
  "web.features.item.homeScreen.body":
    "Instala SpiralClass desde tu navegador. Tu agenda y tus alumnos siempre en el bolsillo — aunque estés fuera de casa.",
  "web.features.item.videoLessons.title": "Videollamada integrada",
  "web.features.item.videoLessons.body":
    "Da la clase dentro de SpiralClass — sin enlaces de Zoom ni apps aparte. Video, notas y materiales en la misma pantalla.",
  "web.features.item.liveCaptions.title": "Subtítulos y traducción en vivo",
  "web.features.item.liveCaptions.body":
    "Hablas español y tu alumno lee subtítulos en inglés en tiempo real. Se activan con un toque y no se guardan.",
